// The only hand-written native code in this package.
//
// Everything else on Android (TextToSpeech, its voices and engines, audio
// focus) is called from Dart through JNI bindings generated by jnigen. This
// file exists for two things Dart cannot do through JNI:
//
// - Subclass UtteranceProgressListener. It is an abstract class, and Dart can
//   only implement Java interfaces; ProgressListener forwards every callback
//   to the Callbacks interface, which Dart implements.
// - Be a Flutter plugin class, so that Gradle builds this module into the app.
//   It registers nothing.
package com.orkitec.speak;

import android.speech.tts.UtteranceProgressListener;
import io.flutter.embedding.engine.plugins.FlutterPlugin;

/** Registers nothing; see the comment at the top of this file. */
public final class SpeakPlugin implements FlutterPlugin {
  @Override
  public void onAttachedToEngine(FlutterPluginBinding binding) {}

  @Override
  public void onDetachedFromEngine(FlutterPluginBinding binding) {}

  /** What the engine reports about an utterance; implemented in Dart. */
  public interface Callbacks {
    void onStart(String utteranceId);

    void onDone(String utteranceId);

    void onStop(String utteranceId, boolean interrupted);

    /** [errorCode] is one of TextToSpeech.ERROR_*, or -1 when not given. */
    void onError(String utteranceId, int errorCode);

    /** Android 8 (API 26) and later, and only from engines that report it. */
    void onRangeStart(String utteranceId, int start, int end);
  }

  /** Forwards every UtteranceProgressListener callback to [Callbacks]. */
  public static final class ProgressListener extends UtteranceProgressListener {
    private final Callbacks callbacks;

    public ProgressListener(Callbacks callbacks) {
      this.callbacks = callbacks;
    }

    @Override
    public void onStart(String utteranceId) {
      callbacks.onStart(utteranceId);
    }

    @Override
    public void onDone(String utteranceId) {
      callbacks.onDone(utteranceId);
    }

    @Override
    public void onStop(String utteranceId, boolean interrupted) {
      callbacks.onStop(utteranceId, interrupted);
    }

    @Override
    @Deprecated
    public void onError(String utteranceId) {
      callbacks.onError(utteranceId, -1);
    }

    @Override
    public void onError(String utteranceId, int errorCode) {
      callbacks.onError(utteranceId, errorCode);
    }

    @Override
    public void onRangeStart(String utteranceId, int start, int end, int frame) {
      callbacks.onRangeStart(utteranceId, start, end);
    }
  }
}
